#include <iostream>
#include <string>
#include <unordered_map>
#include <vector>
#include <mutex>
#include <memory>
#include <cstring>
#include <algorithm>
#include <random>

struct TenantContext {
    uint32_t tenant_id;
    std::string auth_token;
    uint8_t isolation_level; // 0=strict, 1=shared_read, 2=admin
};

struct ConnectionSlot {
    uint32_t owner_tenant;
    uint32_t target_tenant;
    std::string endpoint;
    bool active;
    uint64_t session_nonce;
};

// Constant-time comparison to avoid timing side-channels on secrets.
static bool constant_time_equals(const std::string& a, const std::string& b) {
    // Compare a fixed number of bytes based on the larger length so the
    // number of iterations does not leak the secret length.
    size_t max_len = std::max(a.size(), b.size());
    unsigned char diff = 0;
    diff |= static_cast<unsigned char>(a.size() ^ b.size());
    for (size_t i = 0; i < max_len; i++) {
        unsigned char ca = (i < a.size()) ? static_cast<unsigned char>(a[i]) : 0;
        unsigned char cb = (i < b.size()) ? static_cast<unsigned char>(b[i]) : 0;
        diff |= static_cast<unsigned char>(ca ^ cb);
    }
    return diff == 0;
}

class TenantRegistry {
    std::unordered_map<uint32_t, TenantContext> tenants_;
    std::mutex mu_;
public:
    void register_tenant(uint32_t id, const std::string& token, uint8_t level) {
        std::lock_guard<std::mutex> lk(mu_);
        tenants_[id] = {id, token, level};
    }

    TenantContext* lookup(uint32_t id) {
        std::lock_guard<std::mutex> lk(mu_);
        auto it = tenants_.find(id);
        if (it == tenants_.end()) return nullptr;
        return &it->second;
    }

    bool validate_token(uint32_t id, const std::string& token) {
        std::lock_guard<std::mutex> lk(mu_);
        auto it = tenants_.find(id);
        if (it == tenants_.end()) return false;
        return constant_time_equals(it->second.auth_token, token);
    }
};

class ConnectionPool {
    std::vector<ConnectionSlot> slots_;
    std::mutex mu_;
    std::random_device rng_;

    uint64_t generate_nonce() {
        // Use a cryptographically-seeded RNG source rather than a predictable
        // incrementing counter so session nonces cannot be guessed.
        uint64_t hi = static_cast<uint64_t>(rng_());
        uint64_t lo = static_cast<uint64_t>(rng_());
        return (hi << 32) ^ lo;
    }

public:
    int allocate_slot(uint32_t owner, const std::string& endpoint) {
        std::lock_guard<std::mutex> lk(mu_);
        for (size_t i = 0; i < slots_.size(); i++) {
            if (!slots_[i].active) {
                slots_[i] = {owner, owner, endpoint, true, generate_nonce()};
                return static_cast<int>(i);
            }
        }
        slots_.push_back({owner, owner, endpoint, true, generate_nonce()});
        return static_cast<int>(slots_.size() - 1);
    }

    ConnectionSlot* get_slot(int idx) {
        std::lock_guard<std::mutex> lk(mu_);
        if (idx < 0 || idx >= static_cast<int>(slots_.size())) return nullptr;
        if (!slots_[idx].active) return nullptr;
        return &slots_[idx];
    }

    void release_slot(int idx) {
        std::lock_guard<std::mutex> lk(mu_);
        if (idx >= 0 && idx < static_cast<int>(slots_.size())) {
            slots_[idx].active = false;
        }
    }
};

class ProxyRouter {
    TenantRegistry& registry_;
    ConnectionPool& pool_;

    // Verify that the requesting tenant can access the given slot
    bool check_slot_access(const TenantContext* ctx, const ConnectionSlot* slot) {
        if (!ctx || !slot) return false;

        // Admin can access anything
        if (ctx->isolation_level == 2) return true;

        // Strict isolation: only own slots
        if (ctx->isolation_level == 0) {
            return slot->owner_tenant == ctx->tenant_id;
        }

        // Shared read: can access if target matches
        if (ctx->isolation_level == 1) {
            return slot->target_tenant == ctx->tenant_id ||
                   slot->owner_tenant == ctx->tenant_id;
        }

        return false;
    }

public:
    ProxyRouter(TenantRegistry& reg, ConnectionPool& pool)
        : registry_(reg), pool_(pool) {}

    // Route a request from a tenant to a backend endpoint via a slot
    // Returns: 0 success, -1 auth fail, -2 access denied
    int route_request(uint32_t requesting_tenant, const std::string& token,
                      int slot_idx, const std::string& payload) {

        if (!registry_.validate_token(requesting_tenant, token)) {
            return -1;
        }

        TenantContext* ctx = registry_.lookup(requesting_tenant);
        if (!ctx) return -1;

        ConnectionSlot* slot = pool_.get_slot(slot_idx);
        if (!slot) return -2;

        if (!check_slot_access(ctx, slot)) {
            return -2;
        }

        // Forward the request - update target to reflect routing
        slot->target_tenant = requesting_tenant;

        std::cout << "[PROXY] Tenant " << requesting_tenant 
                  << " routed to " << slot->endpoint 
                  << " via slot " << slot_idx << std::endl;
        return 0;
    }

    // Cross-tenant data relay: tenant A sends data to tenant B's slot
    // This is the controlled sharing mechanism
    int relay_cross_tenant(uint32_t src_tenant, const std::string& src_token,
                           uint32_t dst_tenant, int dst_slot_idx,
                           const std::string& data) {

        if (!registry_.validate_token(src_tenant, src_token)) {
            return -1;
        }

        TenantContext* src_ctx = registry_.lookup(src_tenant);
        TenantContext* dst_ctx = registry_.lookup(dst_tenant);
        if (!src_ctx || !dst_ctx) return -1;

        ConnectionSlot* dst_slot = pool_.get_slot(dst_slot_idx);
        if (!dst_slot) return -2;

        // Authorization check: source must have shared_read or admin
        // AND destination slot must belong to dst_tenant
        if (src_ctx->isolation_level < 1) {
            return -2; // strict isolation cannot relay
        }

        // Verify destination slot ownership using immutable owner field
        if (dst_slot->owner_tenant != dst_tenant) {
            return -2;
        }

        // Additional check: dst_tenant must have explicitly allowed sharing
        if (dst_ctx->isolation_level == 0) {
            return -2; // destination in strict mode rejects incoming relays
        }

        std::cout << "[RELAY] Tenant " << src_tenant 
                  << " -> Tenant " << dst_tenant 
                  << " slot " << dst_slot_idx << std::endl;
        return 0;
    }
};

int main() {
    TenantRegistry registry;
    ConnectionPool pool;
    ProxyRouter router(registry, pool);

    // Setup tenants
    registry.register_tenant(100, "token_alpha", 1);  // shared_read
    registry.register_tenant(200, "token_beta", 0);   // strict
    registry.register_tenant(300, "token_gamma", 1);  // shared_read

    // Tenant 200 allocates a slot
    int slot_b = pool.allocate_slot(200, "internal-db.tenant200.svc:5432");

    // Normal operation: tenant 200 routes through its own slot
    int rc = router.route_request(200, "token_beta", slot_b, "SELECT * FROM secrets");
    std::cout << "Route result: " << rc << std::endl;

    // Tenant 300 attempts cross-tenant relay to tenant 200's slot
    // This is correctly denied: owner check uses immutable owner_tenant,
    // AND tenant 200 is in strict isolation mode
    rc = router.relay_cross_tenant(300, "token_gamma", 200, slot_b, "DROP TABLE users");
    std::cout << "Cross-tenant relay result: " << rc << std::endl;

    return 0;
}
